{
  "name": "Kalkulačka nákladov kotolne",
  "description": "Aplikácia na výpočet nákladov na teplo a energiu pre kotolňu bytového domu. Umožňuje zadávať spotrebu plynu, elektriny, vody a ďalších služieb a vypočíta celkový energetický výkon a náklady v GJ, kWh a EUR. Aplikácia tiež archivuje dáta z predchádzajúcich rokov."
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

import React, { useState, useMemo, useEffect, useCallback } from 'react';
import { DataInputForm } from './components/DataInputForm';
import { ResultsDisplay } from './components/ResultsDisplay';
import { ArchiveView } from './components/ArchiveView';
import { CalculationData, CalculationArchive } from './types';
import { calculateTotals } from './services/calculationService';
import { useLocalStorage } from './hooks/useLocalStorage';
import { Header } from './components/Header';
import { Footer } from './components/Footer';

const createDefaultData = (year: number): CalculationData => ({
  year,
  gas: { consumptionM3: 0, pricePerM3: 0, calorificValueKWhPerM3: 10.55 },
  electricity: { boilerRoomStartKWh: 0, boilerRoomEndKWh: 0, pricePerKWh: 0 },
  water: { boilerRoomStartM3: 0, boilerRoomEndM3: 0, pricePerM3: 0 },
  services: [],
});

const App: React.FC = () => {
  const [archive, setArchive] = useLocalStorage<CalculationArchive>('boiler-room-calculator-archive', {});
  const [currentYear, setCurrentYear] = useState<number>(new Date().getFullYear());
  const [currentData, setCurrentData] = useState<CalculationData>(() => {
    return archive[currentYear] || createDefaultData(currentYear);
  });

  useEffect(() => {
    setCurrentData(archive[currentYear] || createDefaultData(currentYear));
  }, [currentYear, archive]);

  const handleDataChange = useCallback((updatedData: CalculationData) => {
    setCurrentData(updatedData);
    setArchive(prev => ({ ...prev, [updatedData.year]: updatedData }));
  }, [setArchive]);

  const handleYearChange = (year: number) => {
    setCurrentYear(year);
  };

  const results = useMemo(() => calculateTotals(currentData), [currentData]);

  return (
    <div className="min-h-screen flex flex-col bg-slate-100">
      <Header />
      <main className="flex-grow container mx-auto p-4 md:p-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
          <div className="lg:col-span-2">
            <DataInputForm
              data={currentData}
              onUpdate={handleDataChange}
              currentYear={currentYear}
              onYearChange={handleYearChange}
              availableYears={Object.keys(archive).map(Number).sort((a, b) => b - a)}
            />
          </div>
          <div className="lg:col-span-1 space-y-8 sticky top-8">
            <ResultsDisplay results={results} />
            <ArchiveView archive={archive} onSelectYear={handleYearChange} currentYear={currentYear} />
          </div>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default App;

export interface ServiceCost {
  id: string;
  name: string;
  cost: number;
}

export interface CalculationData {
  year: number;
  gas: {
    consumptionM3: number;
    pricePerM3: number;
    calorificValueKWhPerM3: number;
  };
  electricity: {
    boilerRoomStartKWh: number;
    boilerRoomEndKWh: number;
    pricePerKWh: number;
  };
  water: {
    boilerRoomStartM3: number;
    boilerRoomEndM3: number;
    pricePerM3: number;
  };
  services: ServiceCost[];
}

export type CalculationArchive = Record<number, CalculationData>;

export interface CalculationResults {
  totalGJ: number;
  totalKWh: number;
  totalEUR: number;
  gasCost: number;
  electricityCost: number;
  waterCost: number;
  servicesCost: number;
  electricityConsumptionKWh: number;
  waterConsumptionM3: number;
}

import { CalculationData, CalculationResults } from '../types';

const KWH_PER_GJ = 277.778;

export const calculateTotals = (data: CalculationData): CalculationResults => {
  if (!data) {
    return { 
      totalGJ: 0, totalKWh: 0, totalEUR: 0, gasCost: 0, electricityCost: 0, 
      waterCost: 0, servicesCost: 0, electricityConsumptionKWh: 0, waterConsumptionM3: 0 
    };
  }

  const gasCost = (data.gas.consumptionM3 || 0) * (data.gas.pricePerM3 || 0);

  const electricityConsumptionKWh = Math.max(0, (data.electricity.boilerRoomEndKWh || 0) - (data.electricity.boilerRoomStartKWh || 0));
  const electricityCost = electricityConsumptionKWh * (data.electricity.pricePerKWh || 0);

  const waterConsumptionM3 = Math.max(0, (data.water.boilerRoomEndM3 || 0) - (data.water.boilerRoomStartM3 || 0));
  const waterCost = waterConsumptionM3 * (data.water.pricePerM3 || 0);

  const servicesCost = data.services.reduce((acc, service) => acc + (service.cost || 0), 0);

  const totalEUR = gasCost + electricityCost + waterCost + servicesCost;

  const totalKWh = (data.gas.consumptionM3 || 0) * (data.gas.calorificValueKWhPerM3 || 0);
  const totalGJ = totalKWh / KWH_PER_GJ;

  return {
    totalGJ,
    totalKWh,
    totalEUR,
    gasCost,
    electricityCost,
    waterCost,
    servicesCost,
    electricityConsumptionKWh,
    waterConsumptionM3
  };
};

import { useState, useEffect } from 'react';

function getValue<T,>(key: string, initialValue: T): T {
    const saved = window.localStorage.getItem(key);
    if (saved !== null) {
        try {
            return JSON.parse(saved);
        } catch {
            return initialValue;
        }
    }
    return initialValue;
}

export function useLocalStorage<T,>(key: string, initialValue: T): [T, React.Dispatch<React.SetStateAction<T>>] {
    const [value, setValue] = useState<T>(() => {
        return getValue(key, initialValue);
    });

    useEffect(() => {
        window.localStorage.setItem(key, JSON.stringify(value));
    }, [key, value]);

    return [value, setValue];
}

import React from 'react';
import type { CalculationData, ServiceCost } from '../types';

interface InputFieldProps {
  label: string;
  unit: string;
  value: number;
  onChange: (value: number) => void;
  name: string;
}

const InputField: React.FC<InputFieldProps> = ({ label, unit, value, onChange, name }) => (
  <div>
    <label htmlFor={name} className="block text-sm font-medium text-slate-700">{label}</label>
    <div className="mt-1 relative rounded-md shadow-sm">
      <input
        type="number"
        name={name}
        id={name}
        className="block w-full pl-3 pr-12 border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm"
        value={value || ''}
        onChange={(e) => onChange(parseFloat(e.target.value) || 0)}
        placeholder="0.00"
        step="0.01"
      />
      <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
        <span className="text-slate-500 sm:text-sm">{unit}</span>
      </div>
    </div>
  </div>
);

interface DataInputFormProps {
  data: CalculationData;
  onUpdate: (data: CalculationData) => void;
  currentYear: number;
  onYearChange: (year: number) => void;
  availableYears: number[];
}

export const DataInputForm: React.FC<DataInputFormProps> = ({ data, onUpdate, currentYear, onYearChange, availableYears }) => {
  const handleInputChange = (category: keyof CalculationData, field: string, value: number) => {
    onUpdate({
      ...data,
      [category]: {
        ...(data[category] as object),
        [field]: value,
      },
    });
  };

  const handleServiceChange = (index: number, field: keyof Omit<ServiceCost, 'id'>, value: string | number) => {
    const updatedServices = [...data.services];
    updatedServices[index] = { ...updatedServices[index], [field]: value };
    onUpdate({ ...data, services: updatedServices });
  };

  const addService = () => {
    onUpdate({
      ...data,
      services: [...data.services, { id: new Date().toISOString(), name: '', cost: 0 }],
    });
  };

  const removeService = (id: string) => {
    onUpdate({
      ...data,
      services: data.services.filter(service => service.id !== id),
    });
  };

  const handleYearSelectChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
      onYearChange(parseInt(e.target.value));
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow-md space-y-8">
      <div className="flex items-center justify-between">
        <h2 className="text-2xl font-bold text-slate-800">Vstupné údaje pre výpočet</h2>
        <select
            value={currentYear}
            onChange={handleYearSelectChange}
            className="block pl-3 pr-10 py-2 text-base border-gray-300 focus:outline-none focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm rounded-md"
        >
            <option value={new Date().getFullYear()}>{new Date().getFullYear()}</option>
            {availableYears.map(year => (
                <option key={year} value={year}>{year}</option>
            ))}
        </select>
      </div>

      {/* Gas */}
      <section className="space-y-4 p-4 border rounded-md">
        <h3 className="text-lg font-semibold text-indigo-700">Plyn</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <InputField label="Spotreba plynu" unit="m³" name="gas-consumption" value={data.gas.consumptionM3} onChange={(v) => handleInputChange('gas', 'consumptionM3', v)} />
          <InputField label="Cena za m³" unit="€/m³" name="gas-price" value={data.gas.pricePerM3} onChange={(v) => handleInputChange('gas', 'pricePerM3', v)} />
          <InputField label="Výhrevnosť" unit="kWh/m³" name="gas-calorific" value={data.gas.calorificValueKWhPerM3} onChange={(v) => handleInputChange('gas', 'calorificValueKWhPerM3', v)} />
        </div>
      </section>

      {/* Electricity */}
      <section className="space-y-4 p-4 border rounded-md">
        <h3 className="text-lg font-semibold text-indigo-700">Elektrina (Kotolňa)</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <InputField label="Počiatočný stav" unit="kWh" name="elec-start" value={data.electricity.boilerRoomStartKWh} onChange={(v) => handleInputChange('electricity', 'boilerRoomStartKWh', v)} />
          <InputField label="Konečný stav" unit="kWh" name="elec-end" value={data.electricity.boilerRoomEndKWh} onChange={(v) => handleInputChange('electricity', 'boilerRoomEndKWh', v)} />
          <InputField label="Cena za kWh" unit="€/kWh" name="elec-price" value={data.electricity.pricePerKWh} onChange={(v) => handleInputChange('electricity', 'pricePerKWh', v)} />
        </div>
      </section>

      {/* Water */}
      <section className="space-y-4 p-4 border rounded-md">
        <h3 className="text-lg font-semibold text-indigo-700">Voda (Kotolňa)</h3>
        <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
          <InputField label="Počiatočný stav" unit="m³" name="water-start" value={data.water.boilerRoomStartM3} onChange={(v) => handleInputChange('water', 'boilerRoomStartM3', v)} />
          <InputField label="Konečný stav" unit="m³" name="water-end" value={data.water.boilerRoomEndM3} onChange={(v) => handleInputChange('water', 'boilerRoomEndM3', v)} />
          <InputField label="Cena za m³" unit="€/m³" name="water-price" value={data.water.pricePerM3} onChange={(v) => handleInputChange('water', 'pricePerM3', v)} />
        </div>
      </section>

      {/* Services */}
      <section className="space-y-4 p-4 border rounded-md">
        <h3 className="text-lg font-semibold text-indigo-700">Služby a Ostatné Náklady</h3>
        <div className="space-y-3">
          {data.services.map((service, index) => (
            <div key={service.id} className="flex items-center gap-2">
              <input
                type="text"
                placeholder="Názov služby"
                className="flex-grow border-slate-300 rounded-md shadow-sm sm:text-sm"
                value={service.name}
                onChange={(e) => handleServiceChange(index, 'name', e.target.value)}
              />
              <div className="relative rounded-md shadow-sm">
                  <input
                    type="number"
                    placeholder="0.00"
                    className="w-32 pl-3 pr-8 border-slate-300 rounded-md sm:text-sm"
                    value={service.cost || ''}
                    onChange={(e) => handleServiceChange(index, 'cost', parseFloat(e.target.value) || 0)}
                  />
                  <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
                    <span className="text-slate-500 sm:text-sm">€</span>
                  </div>
              </div>
              <button onClick={() => removeService(service.id)} className="p-2 text-red-500 hover:text-red-700 hover:bg-red-100 rounded-full">
                <svg xmlns="http://www.w3.org/2000/svg" className="h-5 w-5" viewBox="0 0 20 20" fill="currentColor">
                  <path fillRule="evenodd" d="M10 18a8 8 0 100-16 8 8 0 000 16zM8.707 7.293a1 1 0 00-1.414 1.414L8.586 10l-1.293 1.293a1 1 0 101.414 1.414L10 11.414l1.293 1.293a1 1 0 001.414-1.414L11.414 10l1.293-1.293a1 1 0 00-1.414-1.414L10 8.586 8.707 7.293z" clipRule="evenodd" />
                </svg>
              </button>
            </div>
          ))}
        </div>
        <button onClick={addService} className="mt-2 text-sm font-medium text-indigo-600 hover:text-indigo-800">+ Pridať ďalšiu položku</button>
      </section>
    </div>
  );
};

import React from 'react';
import type { CalculationResults } from '../types';

interface ResultsDisplayProps {
  results: CalculationResults;
}

const ResultCard: React.FC<{ title: string; value: string; color: string, sub?: string }> = ({ title, value, color, sub }) => (
  <div className={`p-4 rounded-lg flex flex-col justify-between ${color}`}>
    <div>
      <p className="text-sm font-medium text-white/80">{title}</p>
      <p className="text-3xl font-bold text-white">{value}</p>
    </div>
    {sub && <p className="text-sm text-white/80 text-right">{sub}</p>}
  </div>
);

const BreakdownItem: React.FC<{ label: string; value: string; subValue?: string; }> = ({ label, value, subValue }) => (
  <div className="flex justify-between items-baseline py-2 border-b border-slate-200">
    <div>
      <p className="text-sm text-slate-600">{label}</p>
      {subValue && <p className="text-xs text-slate-400">{subValue}</p>}
    </div>
    <p className="text-sm font-semibold text-slate-800">{value}</p>
  </div>
);

export const ResultsDisplay: React.FC<ResultsDisplayProps> = ({ results }) => {
  const formatCurrency = (value: number) => new Intl.NumberFormat('sk-SK', { style: 'currency', currency: 'EUR' }).format(value);
  const formatNumber = (value: number, decimals = 2) => new Intl.NumberFormat('sk-SK', { minimumFractionDigits: decimals, maximumFractionDigits: decimals }).format(value);

  return (
    <div className="bg-white p-6 rounded-lg shadow-md space-y-6">
      <h2 className="text-2xl font-bold text-slate-800">Výsledky výpočtu</h2>
      <div className="grid grid-cols-1 gap-4">
        <ResultCard
          title="Celkové náklady"
          value={formatCurrency(results.totalEUR)}
          color="bg-indigo-600"
        />
        <ResultCard
          title="Vyrobené teplo (GJ)"
          value={formatNumber(results.totalGJ)}
          color="bg-emerald-600"
          sub={`Cena: ${formatCurrency(results.totalEUR / (results.totalGJ || 1))}/GJ`}
        />
         <ResultCard
          title="Vyrobené teplo (kWh)"
          value={formatNumber(results.totalKWh)}
          color="bg-sky-600"
          sub={`Cena: ${formatCurrency(results.totalEUR / (results.totalKWh || 1))}/kWh`}
        />
      </div>
      <div>
        <h3 className="text-lg font-semibold text-slate-700 mb-2">Rozpis nákladov</h3>
        <div className="space-y-1">
          <BreakdownItem label="Plyn" value={formatCurrency(results.gasCost)} />
          <BreakdownItem 
            label="Elektrina" 
            value={formatCurrency(results.electricityCost)} 
            subValue={`${formatNumber(results.electricityConsumptionKWh)} kWh`}
          />
          <BreakdownItem 
            label="Voda" 
            value={formatCurrency(results.waterCost)} 
            subValue={`${formatNumber(results.waterConsumptionM3)} m³`}
          />
          <BreakdownItem label="Služby" value={formatCurrency(results.servicesCost)} />
        </div>
      </div>
       <div className="text-xs text-slate-500 pt-4 border-t">
        <p><strong>Poznámka:</strong> Výpočet tepla je založený primárne na spotrebe a výhrevnosti plynu. Náklady na elektrinu a vodu sú prevádzkové náklady kotolne. Rozdelenie nákladov na teplú úžitkovú vodu (TÚV) a kúrenie vyžaduje samostatné meranie (kalorimetre), ktoré nie je súčasťou tohto výpočtu.</p>
      </div>
    </div>
  );
};

import React from 'react';
import type { CalculationArchive } from '../types';
import { calculateTotals } from '../services/calculationService';

interface ArchiveViewProps {
  archive: CalculationArchive;
  onSelectYear: (year: number) => void;
  currentYear: number;
}

export const ArchiveView: React.FC<ArchiveViewProps> = ({ archive, onSelectYear, currentYear }) => {
  const sortedYears = Object.keys(archive)
    .map(Number)
    .sort((a, b) => b - a);

  if (sortedYears.length === 0) {
    return (
        <div className="bg-white p-6 rounded-lg shadow-md">
            <h3 className="text-lg font-semibold text-slate-700 mb-2">Archív</h3>
            <p className="text-sm text-slate-500">Zatiaľ neboli uložené žiadne dáta. Uložte dáta pre aktuálny rok a zobrazia sa tu.</p>
        </div>
    );
  }

  return (
    <div className="bg-white p-6 rounded-lg shadow-md">
      <h3 className="text-lg font-semibold text-slate-700 mb-2">Archív</h3>
      <div className="max-h-60 overflow-y-auto pr-2">
        <ul className="space-y-2">
          {sortedYears.map((year) => {
            const data = archive[year];
            const results = calculateTotals(data);
            const isActive = year === currentYear;
            return (
              <li key={year}>
                <button
                  onClick={() => onSelectYear(year)}
                  className={`w-full text-left p-3 rounded-md transition-colors duration-200 ${
                    isActive
                      ? 'bg-indigo-100 text-indigo-800 shadow'
                      : 'hover:bg-slate-100'
                  }`}
                >
                  <div className="flex justify-between items-center">
                    <span className={`font-bold ${isActive ? 'text-indigo-800' : 'text-slate-800'}`}>{year}</span>
                    <span className="text-sm font-medium">{new Intl.NumberFormat('sk-SK', { style: 'currency', currency: 'EUR' }).format(results.totalEUR)}</span>
                  </div>
                  <div className="text-xs text-slate-500 mt-1">
                    {new Intl.NumberFormat('sk-SK').format(results.totalGJ)} GJ
                  </div>
                </button>
              </li>
            );
          })}
        </ul>
      </div>
    </div>
  );
};

