import { CalculationData, CalculationResults } from '../types';

const KWH_PER_GJ = 277.778;

export const calculateTotals = (data: CalculationData): CalculationResults => {
  if (!data) {
    return { 
      totalGJ: 0, totalKWh: 0, totalEUR: 0, gasCost: 0, electricityCost: 0, 
      waterCost: 0, servicesCost: 0, electricityConsumptionKWh: 0, waterConsumptionM3: 0,
      gasConsumptionM3: 0
    };
  }

  const gasCost = data.gas.totalPriceEUR || 0;

  let gasConsumptionM3 = 0;
  if (data.gas.meterReplacement) {
      const oldMeterConsumption = Math.max(0, (data.gas.meterReplacement.oldMeterEndM3 || 0) - (data.gas.startM3 || 0));
      const newMeterConsumption = Math.max(0, (data.gas.endM3 || 0) - (data.gas.meterReplacement.newMeterStartM3 || 0));
      gasConsumptionM3 = oldMeterConsumption + newMeterConsumption;
  } else {
      gasConsumptionM3 = Math.max(0, (data.gas.endM3 || 0) - (data.gas.startM3 || 0));
  }

  const electricityConsumptionKWh = Math.max(0, (data.electricity.boilerRoomEndKWh || 0) - (data.electricity.boilerRoomStartKWh || 0));
  const electricityCost = electricityConsumptionKWh * (data.electricity.pricePerKWh || 0);

  const waterConsumptionM3 = Math.max(0, (data.water.boilerRoomEndM3 || 0) - (data.water.boilerRoomStartM3 || 0));
  const waterCost = waterConsumptionM3 * (data.water.pricePerM3 || 0);

  const servicesCost = data.services.reduce((acc, service) => acc + (service.cost || 0), 0);

  const totalEUR = gasCost + electricityCost + waterCost + servicesCost;

  const totalKWh = gasConsumptionM3 * (data.gas.calorificValueKWhPerM3 || 0);
  const totalGJ = totalKWh / KWH_PER_GJ;

  return {
    totalGJ,
    totalKWh,
    totalEUR,
    gasCost,
    electricityCost,
    waterCost,
    servicesCost,
    electricityConsumptionKWh,
    waterConsumptionM3,
    gasConsumptionM3
  };
};

