      <input
        type={type}
        name={name}
        id={name}
        className="block w-full pl-3 pr-12 border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm bg-white text-black disabled:bg-slate-200 disabled:cursor-not-allowed"
        value={value || ''}
        onChange={(e) => onChange(parseFloat(e.target.value.replace(',', '.')) || 0)}
        placeholder="0.00"
        step="any"
      />
      <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
        <span className="text-slate-500 sm:text-sm">{unit}</span>
      </div>
    </div>
  </div>
);

interface DataInputFormProps {
  data: CalculationData;
  onUpdate: (data: CalculationData) => void;
  currentYear: number;
  onYearChange: (year: number) => void;
  onAddNewYear: () => void;
  onToggleLock: () => void;
}

type Tab = 'gas' | 'electricity' | 'water';

export const DataInputForm: React.FC<DataInputFormProps> = ({ data, onUpdate, currentYear, onYearChange, onAddNewYear, onToggleLock }) => {
  const [activeTab, setActiveTab] = useState<Tab>('gas');

  const handleInputChange = (category: keyof CalculationData, field: string, value: number) => {
    onUpdate({
      ...data,
      [category]: {
        ...(data[category] as object),
        [field]: value,
      },
    });
  };

  const handleGasMeterChange = (index: number, field: keyof Omit<GasMeter, 'id'>, value: string | number) => {
    const updatedMeters = [...data.gas.meters];
    const val = typeof value === 'string' ? value : String(value).replace(',', '.');
    updatedMeters[index] = { ...updatedMeters[index], [field]: typeof value === 'string' ? val : parseFloat(val) };
    onUpdate({ ...data, gas: { ...data.gas, meters: updatedMeters }});
  };

  const addGasMeter = () => {
    const newMeter: GasMeter = { id: new Date().toISOString(), meterNumber: '', startM3: 0, endM3: 0 };
    onUpdate({ ...data, gas: { ...data.gas, meters: [...data.gas.meters, newMeter] }});
  };

  const removeGasMeter = (id: string) => {
    const filteredMeters = data.gas.meters.filter(meter => meter.id !== id);
    onUpdate({ ...data, gas: { ...data.gas, meters: filteredMeters }});
  };

  const handleOtherCostChange = (index: number, field: keyof Omit<ServiceCost, 'id'>, value: string | number) => {
    const updatedCosts = [...data.otherCosts];
    const val = typeof value === 'string' ? value : String(value).replace(',', '.');
    updatedCosts[index] = { ...updatedCosts[index], [field]: typeof value === 'string' ? val : parseFloat(val) };
    onUpdate({ ...data, otherCosts: updatedCosts });
  };

  const addOtherCost = () => {
    onUpdate({
      ...data,
      otherCosts: [...data.otherCosts, { id: new Date().toISOString(), name: '', cost: 0 }],
    });
  };

  const removeOtherCost = (id: string) => {
    onUpdate({
      ...data,
      otherCosts: data.otherCosts.filter(cost => cost.id !== id),
    });
  };

  const handleUkTuvChange = (field: keyof CalculationData['ukTuvMeterReadings'], value: number) => {
    onUpdate({
      ...data,
      ukTuvMeterReadings: {
        ...data.ukTuvMeterReadings,
        [field]: value,
      },
    });
  };

  const handleConnectionChange = (connIndex: number, field: keyof Omit<ElectricalConnection, 'id' | 'subMeters'>, value: string | number) => {
    const updatedConnections = [...data.electricity.connections];
    const val = typeof value === 'string' ? value : String(value).replace(',', '.');
    updatedConnections[connIndex] = { ...updatedConnections[connIndex], [field]: typeof value === 'string' ? val : parseFloat(val) };
    onUpdate({ ...data, electricity: { connections: updatedConnections }});
  };

  const handleSubMeterChange = (connIndex: number, smIndex: number, field: keyof Omit<ElectricitySubMeter, 'id'>, value: string | number) => {
    const updatedConnections = [...data.electricity.connections];
    const val = typeof value === 'string' ? value : String(value).replace(',', '.');
    updatedConnections[connIndex].subMeters[smIndex] = { ...updatedConnections[connIndex].subMeters[smIndex], [field]: typeof value === 'string' ? val : parseFloat(val) };
    onUpdate({ ...data, electricity: { connections: updatedConnections }});
  };

  const addSubMeter = (connIndex: number) => {
    const newSubMeter: ElectricitySubMeter = { id: new Date().toISOString(), name: '', startKWh: 0, endKWh: 0 };
    const updatedConnections = [...data.electricity.connections];
    updatedConnections[connIndex].subMeters.push(newSubMeter);
    onUpdate({ ...data, electricity: { connections: updatedConnections }});
  };

  const removeSubMeter = (connIndex: number, smId: string) => {
    const updatedConnections = [...data.electricity.connections];
    updatedConnections[connIndex].subMeters = updatedConnections[connIndex].subMeters.filter(sm => sm.id !== smId);
    onUpdate({ ...data, electricity: { connections: updatedConnections }});
  };


  const isLocked = data.isLocked;
  const formatNumber = (value: number) => new Intl.NumberFormat('sk-SK', { minimumFractionDigits: 2, maximumFractionDigits: 2 }).format(value);

  const renderTabButton = (tab: Tab, label: string) => (
    <button
