                           <InputField label="Počiatočný stav" unit="kWh" name={`sm-start-${connIndex}-${smIndex}`} value={sm.startKWh} onChange={v => handleSubMeterChange(connIndex, smIndex, 'startKWh', v)} />
                           <InputField label="Konečný stav" unit="kWh" name={`sm-end-${connIndex}-${smIndex}`} value={sm.endKWh} onChange={v => handleSubMeterChange(connIndex, smIndex, 'endKWh', v)} />
                           <div>
