                  </div>
                  {conn.name === 'Vchod 25' && (
                     <div className="pt-4 border-t">
                       <label className="block text-sm font-medium text-slate-700">Vypočítané osvetlenie 25</label>
                       <div className="mt-1 p-2 bg-blue-100 text-blue-800 rounded-md font-medium text-sm h-[38px] flex items-center">
                           {formatNumber(calculateOsvetlenie25())} kWh
                       </div>
