            <div className="pt-6 mt-6 border-t">
                <h3 className="text-lg font-semibold text-indigo-700">Dom spolu</h3>
                <div className="p-4 mt-2 border rounded-md bg-green-50">
                    <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                        <div>
                            <label className="block text-sm font-medium text-slate-700">Celková spotreba spolu</label>
                            <div className="mt-1 p-2 bg-slate-200 rounded-md text-slate-800 font-bold h-[38px] flex items-center">
                                {`${formatNumber(totalHouseKWh)} kWh`}
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700">Celková cena spolu</label>
                            <div className="mt-1 p-2 bg-slate-200 rounded-md text-slate-800 font-bold h-[38px] flex items-center">
                                {new Intl.NumberFormat('sk-SK', { style: 'currency', currency: 'EUR' }).format(totalHouseEUR)}
                            </div>
                        </div>
                        <div>
                            <label className="block text-sm font-medium text-slate-700">Priemerná cena</label>
                            <div className="mt-1 p-2 bg-slate-200 rounded-md text-slate-800 font-bold h-[38px] flex items-center">
                                {`${new Intl.NumberFormat('sk-SK', { style: 'currency', currency: 'EUR', minimumFractionDigits: 4 }).format(avgHousePrice)} / kWh`}
