                        <InputField 
                            label="Počet užívateľov Vchod 23" 
                            unit="osôb" 
                            name="users-23" 
                            value={data.electricity.userCounts?.vchod23 || 0}
                            onChange={(v) => handleUserCountChange('vchod23', v)} 
                            integer={true}
                        />
                        <InputField 
                            label="Počet užívateľov Vchod 25" 
                            unit="osôb" 
                            name="users-25" 
                            value={data.electricity.userCounts?.vchod25 || 0}
                            onChange={(v) => handleUserCountChange('vchod25', v)} 
                            integer={true}
                        />
                    </div>
                    <div className="pt-4 border-t grid grid-cols-1 md:grid-cols-3 gap-4 text-sm">
                        <div>
                            <label className="block font-medium text-slate-700">Celkový počet užívateľov</label>
                            <div className="mt-1 p-2 bg-slate-200 rounded-md text-slate-800 font-bold h-[38px] flex items-center">{totalUsers} osôb</div>
                        </div>
                        <div>
                            <label className="block font-medium text-slate-700">Podiel Vchod 23</label>
                            <div className="mt-1 p-2 bg-slate-100 rounded-md text-slate-800 font-medium h-[38px] flex items-center">{percentage23} %</div>
                        </div>
                        <div>
