  const conn25 = data.electricity.connections.find(c => c.name === 'Vchod 25');

  const totalHouseKWh = (conn23?.totalKWh || 0) + (conn25?.totalKWh || 0);
  const totalHouseEUR = (conn23?.totalEUR || 0) + (conn25?.totalEUR || 0);
