const createDataFromPreviousYear = (prevData: CalculationData): CalculationData => {
    const newYear = prevData.year + 1;
    return {
        year: newYear,
        isLocked: false,
        gas: {
            meters: prevData.gas.meters.map(meter => ({
                id: `${new Date().toISOString()}-${meter.meterNumber}`,
                meterNumber: meter.meterNumber,
                startM3: meter.endM3,
                endM3: meter.endM3,
            })),
            totalPriceEUR: 0,
        },
        gasKwhPerM3: prevData.gasKwhPerM3,
        ukTuvMeterReadings: {
            ukStartGJ: prevData.ukTuvMeterReadings.ukEndGJ,
            ukEndGJ: prevData.ukTuvMeterReadings.ukEndGJ,
            tuvStartGJ: prevData.ukTuvMeterReadings.tuvEndGJ,
            tuvEndGJ: prevData.ukTuvMeterReadings.tuvEndGJ,
        },
        electricity: {
          connections: prevData.electricity.connections.map(conn => ({
            ...conn,
            id: `${new Date().toISOString()}-${conn.name}`,
            meterNumber: conn.meterNumber,
            monthlyReadings: Array.from({ length: 12 }, (_, i) => ({ month: i + 1, kWh: 0, EUR: 0 })),
            subMeters: conn.subMeters.map(sm => ({
              ...sm,
              id: `${new Date().toISOString()}-${sm.name}`,
              startKWh: sm.endKWh,
              endKWh: sm.endKWh,
            }))
          })),
          userCounts: { ...prevData.electricity.userCounts },
        },
        water: {
            meterNumber: prevData.water.meterNumber,
            monthlyReadings: Array.from({ length: 12 }, (_, i) => ({ month: i + 1, m3: 0, EUR: 0 })),
            sewerageCost: 0,
        },
        mandateContractMonthlyCost: prevData.mandateContractMonthlyCost,
        repairFundAnnualCost: prevData.repairFundAnnualCost,
        otherCosts: prevData.otherCosts.map(cost => ({
            id: `${new Date().toISOString()}-${cost.name}`,
            name: cost.name,
            cost: cost.cost,
        })),
    };
};


const App: React.FC = () => {
  const [archive, setArchive] = useLocalStorage<CalculationArchive>('boiler-room-calculator-archive', {});
  const [currentYear, setCurrentYear] = useState<number>(() => {
    const years = Object.keys(archive).map(Number);
    return years.length > 0 ? Math.max(...years) : new Date().getFullYear() - 1;
  });

  const [currentData, setCurrentData] = useState<CalculationData>(() => {
    return archive[currentYear] || createDefaultData(currentYear);
  });

  useEffect(() => {
    setCurrentData(archive[currentYear] || createDefaultData(currentYear));
  }, [currentYear, archive]);

  const handleDataChange = useCallback((updatedData: CalculationData) => {
    setCurrentData(updatedData);
    setArchive(prev => ({ ...prev, [updatedData.year]: updatedData }));
  }, [setArchive]);

  const handleYearChange = (year: number) => {
    if(year > 1900 && year < 2100) {
      setCurrentYear(year);
    }
  };

  const handleAddNewYear = () => {
    const years = Object.keys(archive).map(Number);
    const latestYear = years.length > 0 ? Math.max(...years) : new Date().getFullYear() - 1;
    const newYear = latestYear + 1;

    let newData: CalculationData;
    const latestYearData = archive[latestYear];

    if (latestYearData) {
        newData = createDataFromPreviousYear(latestYearData);
    } else {
        newData = createDefaultData(newYear);
    }

    // Check if new year already exists from manual input to prevent overwriting
    if (!archive[newYear]) {
      setArchive(prev => ({ ...prev, [newYear]: newData }));
    }
    setCurrentYear(newYear);
  };

  const handleToggleLock = () => {
    const updatedData = { ...currentData, isLocked: !currentData.isLocked };
    handleDataChange(updatedData);
  };

  const results = useMemo(() => calculateTotals(currentData), [currentData]);

  return (
    <div className="min-h-screen flex flex-col bg-slate-100">
      <Header />
      <main className="flex-grow container mx-auto p-4 md:p-8">
        <div className="grid grid-cols-1 lg:grid-cols-3 gap-8 items-start">
          <div className="lg:col-span-2">
            <DataInputForm
              data={currentData}
              onUpdate={handleDataChange}
              currentYear={currentYear}
              onYearChange={handleYearChange}
              onAddNewYear={handleAddNewYear}
              onToggleLock={handleToggleLock}
            />
          </div>
          <div className="lg:col-span-1 space-y-8 sticky top-8">
            <ResultsDisplay results={results} />
            <ArchiveView archive={archive} onSelectYear={handleYearChange} currentYear={currentYear} />
          </div>
        </div>
      </main>
      <Footer />
    </div>
  );
};

export default App;

import { CalculationData, CalculationResults, ElectricitySubMeter } from '../types';

const KWH_PER_GJ = 277.778;

export const calculateTotals = (data: CalculationData): CalculationResults => {
  if (!data) {
    return { 
      totalEUR: 0, gasCost: 0, electricityCost: 0, waterCost: 0, servicesCost: 0, 
      electricityConsumptionKWh: 0, waterConsumptionM3: 0, gasConsumptionM3: 0,
      totalGJ: 0, totalKWh: 0,
      uk_GJ: 0, uk_KWh: 0, uk_EUR: 0,
      tuv_GJ: 0, tuv_KWh: 0, tuv_EUR: 0
    };
  }

  const gasCost = data.gas.totalPriceEUR || 0;

  const gasConsumptionM3 = data.gas.meters.reduce((total, meter) => {
    const consumption = Math.max(0, (meter.endM3 || 0) - (meter.startM3 || 0));
    return total + consumption;
  }, 0);

  // --- Electricity Calculation ---
  let electricityConsumptionKWh = 0;
  let electricityCost = 0;

  if (data.electricity && data.electricity.connections) {
    for (const connection of data.electricity.connections) {
      const boilerRoomSubMeter = connection.subMeters.find(sm => sm.name.toLowerCase() === 'kotolňa');
      if (boilerRoomSubMeter) {
        const consumption = Math.max(0, (boilerRoomSubMeter.endKWh || 0) - (boilerRoomSubMeter.startKWh || 0));
        electricityConsumptionKWh += consumption;

        const connectionTotalKWh = (connection.monthlyReadings || []).reduce((sum, r) => sum + (r.kWh || 0), 0);
        const connectionTotalEUR = (connection.monthlyReadings || []).reduce((sum, r) => sum + (r.EUR || 0), 0);
        const avgPricePerKWh = connectionTotalKWh > 0 ? connectionTotalEUR / connectionTotalKWh : 0;

        electricityCost += consumption * avgPricePerKWh;
        break; // Assuming only one boiler room meter in the whole system
      }
    }
  }

  // --- Water Calculation ---
  const waterConsumptionM3 = (data.water.monthlyReadings || []).reduce((sum, r) => sum + (r.m3 || 0), 0);
  const waterCost = (data.water.monthlyReadings || []).reduce((sum, r) => sum + (r.EUR || 0), 0) + (data.water.sewerageCost || 0);

  const mandateCost = (data.mandateContractMonthlyCost || 0) * 12;
  const repairFundCost = data.repairFundAnnualCost || 0;
  const otherCostsSum = data.otherCosts.reduce((acc, service) => acc + (service.cost || 0), 0);
  const servicesCost = mandateCost + repairFundCost + otherCostsSum;

  const totalEUR = gasCost + electricityCost + waterCost + servicesCost;

  const totalKWh = gasConsumptionM3 * (data.gasKwhPerM3 || 0);
  const totalGJ = totalKWh / KWH_PER_GJ;

  const ukMeterConsumptionGJ = Math.max(0, (data.ukTuvMeterReadings.ukEndGJ || 0) - (data.ukTuvMeterReadings.ukStartGJ || 0));
  const tuvMeterConsumptionGJ = Math.max(0, (data.ukTuvMeterReadings.tuvEndGJ || 0) - (data.ukTuvMeterReadings.tuvStartGJ || 0));
  const totalMeterConsumptionGJ = ukMeterConsumptionGJ + tuvMeterConsumptionGJ;

  let ukRatio = 0.5;
  let tuvRatio = 0.5;

  if (totalMeterConsumptionGJ > 0) {
    ukRatio = ukMeterConsumptionGJ / totalMeterConsumptionGJ;
    tuvRatio = tuvMeterConsumptionGJ / totalMeterConsumptionGJ;
  }

  // Split total generated heat
  const uk_GJ = totalGJ * ukRatio;
  const tuv_GJ = totalGJ * tuvRatio;
  const uk_KWh = totalKWh * ukRatio;
  const tuv_KWh = totalKWh * tuvRatio;

  // Split ONLY gas cost, as other costs are common for the boiler room
  const uk_EUR = gasCost * ukRatio;
  const tuv_EUR = gasCost * tuvRatio;

  return {
    totalEUR,
    gasCost,
    electricityCost,
    waterCost,
    servicesCost,
    electricityConsumptionKWh,
    waterConsumptionM3,
    gasConsumptionM3,
    totalGJ,
    totalKWh,
    uk_GJ,
    uk_KWh,
    uk_EUR,
    tuv_GJ,
    tuv_KWh,
    tuv_EUR,
  };
};

import React, { useState } from 'react';
import type { CalculationData, ServiceCost, GasMeter, ElectricalConnection, ElectricitySubMeter } from '../types';

interface InputFieldProps {
  label: string;
  unit: string;
  value: number;
  onChange: (value: number) => void;
  name: string;
  type?: 'number' | 'text';
  integer?: boolean;
}

const InputField: React.FC<InputFieldProps> = ({ label, unit, value, onChange, name, type = 'number', integer = false }) => (
  <div>
    <label htmlFor={name} className="block text-sm font-medium text-slate-700">{label}</label>
    <div className="mt-1 relative rounded-md shadow-sm">
      <input
        type={type}
        name={name}
        id={name}
        className="block w-full pl-3 pr-12 border-slate-300 rounded-md focus:ring-indigo-500 focus:border-indigo-500 sm:text-sm bg-white text-black disabled:bg-slate-200 disabled:cursor-not-allowed"
        value={value || ''}
        onChange={(e) => {
          const val = integer 
            ? parseInt(e.target.value, 10) 
            : parseFloat(e.target.value.replace(',', '.'));
          onChange(isNaN(val) ? 0 : val);
        }}
        placeholder={integer ? "0" : "0.00"}
        step={integer ? "1" : "any"}
      />
      <div className="absolute inset-y-0 right-0 pr-3 flex items-center pointer-events-none">
        <span className="text-slate-500 sm:text-sm">{unit}</span>
      </div>
    </div>
  </div>
);

interface DataInputFormProps {
  data: CalculationData;
  onUpdate: (data: CalculationData) => void;
  currentYear: number;
  onYearChange: (year: number) => void;
  onAddNewYear: () => void;
  onToggleLock: () => void;
}

type Tab = 'gas' | 'electricity' | 'water' | 'sumar';
type ElectricityView = 'overview' | 'monthly';
type WaterView = 'overview' | 'monthly';

export const DataInputForm: React.FC<DataInputFormProps> = ({ data, onUpdate, currentYear, onYearChange, onAddNewYear, onToggleLock }) => {
  const [activeTab, setActiveTab] = useState<Tab>('gas');
  const [electricityView, setElectricityView] = useState<ElectricityView>('overview');
  const [waterView, setWaterView] = useState<WaterView>('overview');

  const handleInputChange = (category: keyof CalculationData, field: string, value: number) => {
    onUpdate({
      ...data,
      [category]: {
        ...(data[category] as object),
        [field]: value,
      },
    });
  };

  const handleGasMeterChange = (index: number, field: keyof Omit<GasMeter, 'id'>, value: string | number) => {
    const updatedMeters = [...data.gas.meters];
    const val = typeof value === 'string' ? value : String(value).replace(',', '.');
    updatedMeters[index] = { ...updatedMeters[index], [field]: typeof value === 'string' ? val : parseFloat(val) };
    onUpdate({ ...data, gas: { ...data.gas, meters: updatedMeters }});
  };

  const addGasMeter = () => {
    const newMeter: GasMeter = { id: new Date().toISOString(), meterNumber: '', startM3: 0, endM3: 0 };
    onUpdate({ ...data, gas: { ...data.gas, meters: [...data.gas.meters, newMeter] }});
  };

  const removeGasMeter = (id: string) => {
    const filteredMeters = data.gas.meters.filter(meter => meter.id !== id);
    onUpdate({ ...data, gas: { ...data.gas, meters: filteredMeters }});
  };

  const handleOtherCostChange = (index: number, field: keyof Omit<ServiceCost, 'id'>, value: string | number) => {
    const updatedCosts = [...data.otherCosts];
    const val = typeof value === 'string' ? value : String(value).replace(',', '.');
    updatedCosts[index] = { ...updatedCosts[index], [field]: typeof value === 'string' ? val : parseFloat(val) };
    onUpdate({ ...data, otherCosts: updatedCosts });
  };

  const addOtherCost = () => {
    onUpdate({
      ...data,
      otherCosts: [...data.otherCosts, { id: new Date().toISOString(), name: '', cost: 0 }],
    });
  };

  const removeOtherCost = (id: string) => {
    onUpdate({
      ...data,
      otherCosts: data.otherCosts.filter(cost => cost.id !== id),
    });
  };

  const handleUkTuvChange = (field: keyof CalculationData['ukTuvMeterReadings'], value: number) => {
    onUpdate({
      ...data,
      ukTuvMeterReadings: {
        ...data.ukTuvMeterReadings,
        [field]: value,
      },
    });
  };

  const handleElectricityChange = (
    connIndex: number, 
    field: 'meterNumber' | 'monthlyReadings', 
    value: string | { monthIndex: number; key: 'kWh' | 'EUR'; val: number }
  ) => {
    const updatedConnections = data.electricity.connections.map((conn, cIdx) => {
        if (cIdx !== connIndex) return conn;

        if (field === 'meterNumber' && typeof value === 'string') {
            return { ...conn, meterNumber: value };
        }

        if (field === 'monthlyReadings' && typeof value === 'object') {
            const updatedReadings = conn.monthlyReadings.map((reading, rIdx) => {
                if(rIdx !== value.monthIndex) return reading;
                return { ...reading, [value.key]: value.val };
            });
            return { ...conn, monthlyReadings: updatedReadings };
        }
        return conn;
    });
    onUpdate({ ...data, electricity: { ...data.electricity, connections: updatedConnections }});
  };

  const handleWaterChange = (
    field: 'meterNumber' | 'monthlyReadings' | 'sewerageCost', 
    value: string | number | { monthIndex: number; key: 'm3' | 'EUR'; val: number }
  ) => {
    let updatedWaterData = { ...data.water };

    if (field === 'meterNumber' && typeof value === 'string') {
        updatedWaterData.meterNumber = value;
    } else if (field === 'sewerageCost' && typeof value === 'number') {
        updatedWaterData.sewerageCost = value;
    } else if (field === 'monthlyReadings' && typeof value === 'object') {
        const updatedReadings = updatedWaterData.monthlyReadings.map((reading, rIdx) => {
            if (rIdx !== value.monthIndex) return reading;
            return { ...reading, [value.key]: value.val };
        });
        updatedWaterData.monthlyReadings = updatedReadings;
    }

    onUpdate({ ...data, water: updatedWaterData });
  };


  const handleSubMeterChange = (connIndex: number, smIndex: number, field: keyof Omit<ElectricitySubMeter, 'id' | 'name'>, value: number) => {
    const updatedConnections = data.electricity.connections.map((conn, cIdx) => {
        if (cIdx !== connIndex) return conn;
        const updatedSubMeters = conn.subMeters.map((sm, sIdx) => {
            if (sIdx !== smIndex) return sm;
            return { ...sm, [field]: value };
        });
        return { ...conn, subMeters: updatedSubMeters };
    });
    onUpdate({ ...data, electricity: { ...data.electricity, connections: updatedConnections }});
  };

  const handleUserCountChange = (vchod: 'vchod25' | 'vchod23', value: number) => {
    onUpdate({
        ...data,
        electricity: {
            ...data.electricity,
            userCounts: {
