  const kotolnaSubMeter = conn23?.subMeters.find(sm => sm.name === 'Kotolňa');
  const kotolnaKWh = (kotolnaSubMeter?.endKWh || 0) - (kotolnaSubMeter?.startKWh || 0);
  const kotolnaEur = kotolnaKWh * avgHousePrice;
