                   <div className="p-4 bg-slate-50 rounded-md border space-y-4">
                      <h4 className="font-semibold text-slate-800">Teplá úžitková voda</h4>
                      <div className="grid grid-cols-1 sm:grid-cols-3 gap-4 items-end">
